        input [7:0] data;
        reg [15:0] crc;
        integer i;
        begin
            crc = state ^ {data, 8'b0};
            for (i = 0; i < 8; i = i + 1) begin
                if (crc[15])
                    crc = (crc << 1) ^ 16'h1021;
                else
                    crc = crc << 1;
            end
            crc16_update = crc;
        end
    endfunction

